mapper.select:
SELECT u.* FROM hyperlink_task_account_usage u
INNER JOIN hyperlink_task_round_account a ON a.task_account_usage_id=u.id
  AND a.hyperlink_task_round_id=#{roundId} AND a.assignment_status=1
WHERE u.hyperlink_task_id=#{taskId}
  AND u.usage_status=1 AND u.next_send_at<=#{now} AND u.in_flight_count<#{maxInFlight}
  AND (u.success_limit=0 OR u.successful_send_count+u.reserved_success_slot_count<u.success_limit)
ORDER BY u.next_send_at, a.selection_no, u.id LIMIT #{limit}
